INSERT OR IGNORE INTO planner_modules (id,module_code,name,description,purpose,functional_requirements,acceptance_criteria,status,priority,owner_name,target_release,risk_level,progress,approval_state,created_by,created_at,updated_at)
VALUES ('module-email-marketing','GR-EMAIL','Email Marketing','Organization-scoped email campaigns integrated with the Gather supporter CRM.','Help nonprofits segment supporters, design compliant fundraising emails, schedule safe sends, and measure real engagement and attributable outcomes.','Campaign dashboard; saved audiences; responsive block editor; templates; sending identities; list health; SES delivery boundary; OpenSRS setup boundary; Reoon verification boundary; automations; reporting; consent and suppression enforcement.','Authorized organizers can create drafts and audiences; contacts remain CRM-owned; unsafe recipients are excluded; provider states are honest; sandbox cannot bulk-send; reports use recorded delivery events only.','In Progress','Critical','Gather Product','Sandbox','High',55,'Approved','system',1795000000000,1795000000000);

INSERT OR IGNORE INTO planner_features (id,module_id,name,description,functional_specification,acceptance_criteria,status,approval_state,created_by,created_at,updated_at) VALUES
('email-feature-dashboard','module-email-marketing','Campaign dashboard and reporting','Campaign performance, filters, previews, and provider readiness.','Display organization-scoped delivered, estimated opens, clicks, unsubscribes, and reliable attribution.','No demonstration metrics; empty states are accurate; campaign rows open real records.','In Progress','Approved','system',1795000000000,1795000000000),
('email-feature-audiences','module-email-marketing','Audiences and CRM integration','Saved rule-based audiences over canonical CRM supporters.','Evaluate supported contact attributes while enforcing consent, suppression, and validation eligibility.','Audience counts are organization-scoped and ineligible contacts cannot be selected for sending.','In Progress','Approved','system',1795000000000,1795000000000),
('email-feature-designer','module-email-marketing','Campaign designer and templates','Responsive fundraising email composition and reusable templates.','Support content blocks, personalization-safe previews, compliance footer, desktop/mobile preview, drafts, and schedules.','Organizer approval is required; no AI or automation sends without approval.','In Progress','Approved','system',1795000000000,1795000000000),
('email-feature-delivery','module-email-marketing','SES delivery and reputation safety','Server-side delivery, scheduling, webhooks, throttling, bounces, complaints, and audit history.','Keep marketing delivery separate from transactional email and enforce organization limits and suppression rules.','Sandbox cannot send to real customers; missing SES configuration is shown as blocked.','Blocked','Approved','system',1795000000000,1795000000000),
('email-feature-domains','module-email-marketing','Professional domains and sending identities','Existing-domain verification and approval-gated OpenSRS provisioning.','Expose DNS/authentication readiness without registering domains or changing DNS automatically.','No purchase or DNS mutation occurs without explicit authorized approval.','Blocked','Approved','system',1795000000000,1795000000000),
('email-feature-verification','module-email-marketing','List health and Reoon verification','Contact validation classifications and eligible-send analysis.','Provider-specific logic remains behind a service boundary and paid credits require configured limits.','Undeliverable, unsubscribed, and complained contacts remain suppressed.','Blocked','Approved','system',1795000000000,1795000000000),
('email-feature-automations','module-email-marketing','Marketing automations','Event-based invitations, reminders, previews, follow-ups, and thank-you workflows.','Automations use organization triggers, delays, eligibility checks, pause/resume, and execution history.','Transactional auction notifications are not duplicated or interrupted.','In Progress','Approved','system',1795000000000,1795000000000);
